      if (members.length < 2) continue;
      const l = Math.hypot(sx, sy, sz) || 1;
      sx /= l; sy /= l; sz /= l;
      for (const m of members) { na[m * 3] = sx; na[m * 3 + 1] = sy; na[m * 3 + 2] = sz; }
