const KIND_ICON: Partial<Record<Poi['kind'], string>> = { mission: ICON.flag, repair: ICON.wrench, drone: ICON.warn, rig: ICON.truck, station: ICON.gps };

// ── HUD: one low-res canvas, drawn in the pixel font ───────────────
